<?php
require_once __DIR__.'/includes/module.php'; require_roles(['admin','admin_humas']);
$page_title='Prospek Peserta';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$institution=trim($_POST['institution']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$interest=trim($_POST['interest']??'');$source=trim($_POST['source']??'');$follow=($_POST['follow_up_date']??'')?:null;$status=$_POST['status']??'Baru';$notes=trim($_POST['notes']??'');$allowed=['Baru','Dihubungi','Tertarik','Mendaftar','Tidak Berminat'];if($name&&in_array($status,$allowed,true)){ $q=$pdo->prepare('INSERT INTO prospects(name,institution,phone,email,interest,source,follow_up_date,status,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$name,$institution?:null,$phone?:null,$email?:null,$interest?:null,$source?:null,$follow,$status,$notes?:null,$_SESSION['user']['id']]);flash('Prospek berhasil ditambahkan.');}else flash('Nama prospek wajib diisi.');header('Location: prospects.php');exit;}
$rows=$pdo->query('SELECT * FROM prospects ORDER BY created_at DESC')->fetchAll();require __DIR__.'/includes/header.php';show_flash();
?>
<section class="panel"><div class="panel-head"><h3>Tambah Prospek Peserta</h3></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Nama calon peserta *</label><input name="name" required></div><div class="field"><label>Instansi</label><input name="institution"></div><div class="field"><label>No. HP/WhatsApp</label><input name="phone"></div><div class="field"><label>Email</label><input type="email" name="email"></div><div class="field"><label>Minat pelatihan</label><input name="interest"></div><div class="field"><label>Sumber prospek</label><input name="source" placeholder="WhatsApp, telepon, referensi..."></div><div class="field"><label>Tanggal tindak lanjut</label><input type="date" name="follow_up_date"></div><div class="field"><label>Status</label><select name="status"><option>Baru</option><option>Dihubungi</option><option>Tertarik</option><option>Mendaftar</option><option>Tidak Berminat</option></select></div><div class="field full"><label>Catatan</label><textarea name="notes" rows="2"></textarea></div></div><div class="form-actions"><button class="btn">Simpan Prospek</button></div></form></section>
<section class="panel"><div class="panel-head"><h3>Daftar Prospek</h3></div><table><thead><tr><th>Nama</th><th>Instansi</th><th>Kontak</th><th>Minat</th><th>Tindak Lanjut</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">Belum ada prospek.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['institution']?:'-')?></td><td><?=e($r['phone']?:$r['email']?:'-')?></td><td><?=e($r['interest']?:'-')?></td><td><?=e($r['follow_up_date']?:'-')?></td><td><?=e($r['status'])?></td></tr><?php endforeach;endif;?></tbody></table></section>
